import React, {
    useContext
} from "react"
import {
    Link,
    NavLink,
    navigate,
    useNavigate
} from "react-router-dom"
import backIcon from "../../assets/images/back-icon.png"
import { AppState } from "../.."
import {
    EntryHeader,
    EntryExample,
    EntryExchanges,
    EntryDescription,
    EntryTable,
    EntryCode,
    EntryTags
} from "../../components/EntryComponents"

export default function Entry({ tags, name, description, inputs, outputs, code, deprecateNotice, status, example, table, noApi, isPopup, patch, page, link, expLink, section, type, original }) {
    const { apiPages, tagCategories, selectedTags, updateTags, tdPatch } = useContext(AppState);
    let navigate = useNavigate()
    patch = patch || original
    const hasPatch = patch !== null
    const experimental = hasPatch && patch > tdPatch
    const peers = ['Server', 'Client'].filter(v => tags.includes(v))
    const peer = peers.length === 1 && peers[0]
    const popupStyle = isPopup 
        ? `"header header header back"
        "example example example back"`
        : `"header header header header"
        "example example example example"`

    const funcStyle = {
        gridTemplateAreas: `
            ${popupStyle}
            "exchanges exchanges exchanges exchanges"
            "description description description description"
            "table table table table"
            "code code code code"
            "tags tags tags tags"
            ". . . ."
        `
    }

    const headerElement = (
        <EntryHeader
            page={page}
            experimental={experimental}
            name={name}
            status={status}
            peer={peer}
        />)

    const exampleElement = (
        <EntryExample
            name={name}
            type={type}
            inputs={inputs}
            outputs={outputs}
        />)

    const exchangesElement = (
        <EntryExchanges
            type={type}
            inputs={inputs}
            outputs={outputs}
        />)

    const descriptionElement = (
        <EntryDescription
            deprecateNotice={deprecateNotice}
            text={description}
        />)

    const tableElement = (
        <EntryTable
            table={table}
        />)
    
    const codeElement = (
        <EntryCode
            type={type}
            code={example}
        />)

    const tagElement = (
        <EntryTags
            name={name}
            tags={tags}
            experimental={experimental}
            link={link}
            expLink={expLink}
            section={section}
            noApi={noApi}
        />)

    return (
        <div className="func" style={funcStyle}>
            {headerElement}
            
            {exampleElement}

            {exchangesElement}

            {descriptionElement}

            {tableElement}

            {codeElement}
            
            {tagElement}
        </div>
    )
}