import React from "react";
import { useMyNavigate } from "./MyNavigate";

// Parses [type/id] tokens from plain text
function parseSmartTokens(text) {
	const regex = /\[([a-z0-9]+:[a-zA-Z0-9._-]*)\]/g;
	const parts = [];
	let lastIndex = 0;

	text.replace(regex, (match, path, offset) => {
		if (offset > lastIndex) {
			parts.push({ type: "text", value: text.slice(lastIndex, offset) });
		}
		parts.push({ type: "token", value: path });
		lastIndex = offset + match.length;
	});

	if (lastIndex < text.length) {
		parts.push({ type: "text", value: text.slice(lastIndex) });
	}

	return parts;
}

export default function TokenText({ className, style = {}, text }) {
	const parts = parseSmartTokens(text);
	let navigate = useMyNavigate();

	return (
		<span>
			{parts.map((part, index) => {
				if (part.type === "token") {
					const [section, id] = part.value.split(":");
					const label = id || section;
					return (
						<span
							key={index}
							className="api--token"
							style={style}
							onMouseUp={() =>
								navigate("/api/:section/:id", {
									section: section,
									id: id
							})}
						>
							{label}
						</span>
					);
				}
				return (
					<span
						className={className}
						style={style}
					>
							{part.value}
					</span> );
			})}
		</span>
	);
}
