import { useState } from "react";
import { EntryCode, EntryTable } from "../../components/EntryComponents";
import maximizeIcon from "../../assets/images/maximize_arrow.png";
import minimizeIcon from "../../assets/images/minimize_arrow.png";
import TokenText from "../../components/TokenText";

export default function ApiRegistry({
  name,
  type,
  description = "",
  children,
  path = name,
  sample,
  table,
  substitute,
  notouch,
  searchQuery,
  selectedTags
}) {
  const [maximized, setMaximized] = useState(false);
  const regTypes = {
    boolean: {
      name: "Bool",
      alias: "bool",
      sample: true,
    },
    float: {
      name: "Float",
      alias: "num",
      sample: 3.14,
    },
    integer: {
      name: "Int",
      alias: "num",
      sample: 314,
    },
    string: {
      name: "String",
      alias: "str",
      sample: '"Hello world!"',
    },
  };

  const regExchange = (name, path, sample) => {
    return `${name}("${path}"${sample ? `, ${sample}` : ""})`;
  };
  let code = "";

  if (children) {
    code = code + `local keys = ${regExchange("ListKeys", path)}\n`;
  }

  if (type) {
    const entry = regTypes[type];
    const getter = `local ${name} = Get${regExchange(entry.name, path)}\n`
    const setter = notouch
        ? ""
        : `Set${regExchange(entry.name, path, sample ?? regTypes[type].sample)}`
    
    code = code + getter + setter;
  }

  const registryCode =
    type || children ? <EntryCode type={"function"} code={code} /> : false;

  const registryTable = <EntryTable table={table} />;

  return (
    <div style={{ color: "white" }}>
      <div
        className="api--tag"
        style={{
            display: "flex",
          margin: "5px",
          padding: "5px 7px 5px 7px",
          height: "auto",
          width: "contain-content",
          maxWidth: "200px",
          flexDirection: "row",
          alignItems: "center"
        }}
        onMouseUp={() => {
          setMaximized((state) => !state);
        }}
      >
        <img
            src={maximized ? minimizeIcon : maximizeIcon}
            height="10px"
            align="center middle"
            style={{ marginRight: "5px", color: "" }}
            alt=""
        />
        {substitute ? `<${name}>` : name}
      </div>
      {maximized && (
        <div>
          <p>
            {/* {type} */}
            <TokenText
              className="func--text"
              text={description}
            />
            {registryCode}
            {registryTable}
          </p>
          <div style={{ marginLeft: "20px" }}>
            {children?.length > 0 &&
              children.map(
                (child) =>
                  (
                    <ApiRegistry
                      {...child}
                      path={`${path}.${
                        child.substitute ? `<${child.name}>` : child.name
                      }`}
                      searchQuery={searchQuery}
                      selectedTags={selectedTags}
                    />
                  ) || false
              )}
          </div>
        </div>
      )}
    </div>
  );
}
