import {
    Link,
    NavLink,
    useParams,
    useLocation
} from "react-router-dom"
import loginIcon from "../assets/images/avatar-icon.png"
import { AppState } from "..";
import { useContext } from "react";
import Suggestions from "./Suggestions";

export default function Header() {
    const { apiPages, tagCategories, selectedTags, searchQuery, updateQuery } = useContext(AppState);

    const location = useLocation().pathname
    const locationArray = location.split("/")

    /*console.log(locationArray)*/
    
    function fakeLogOut() {
        localStorage.removeItem("loggedin")
    }

    const dir = locationArray.map( (loc, index) => {
        if (loc) {
            const name = `${loc[0].toUpperCase()}${loc.slice(1)}`
            const lastPos = location.indexOf(loc) + loc.length
            const link = location.slice(0, lastPos)
            return (
                <Link
                    key={link}
                    className="header--dir-link"
                    to={link}
                >
                    {name}
                </Link>
            )
        }
    })

    const apiLinks = apiPages?.value.map( page => {
        return !page.test
        ? (<NavLink
            onClick={() => {
                selectedTags.value = [];
                searchQuery.value = "";
                updateQuery("");
            }}
            to={`/api/${page.title.toLowerCase()}`}
            className={({ isActive }) => isActive ? "active-nav" : null }
        >
            {page.title}
        </NavLink>)
        : ""
    })

    const betaStyle = {
        marginLeft: "10px",
        fontSize: "18px",
        backgroundColor: "red",
        padding: "1px 3px 1px 3px",
        borderRadius: "5px",
        color: "white"
    }
    const betaNotice = (
        <p
            style={betaStyle}
        >
            BETA
        </p>)
    
    return (
        <div className="header">
            <header>
                <Link
                    className="site-logo"
                    to="/"
                    style={{display: "flex", alignItems: "center"}}
                >
                    Unofficial TD Docs
                    {betaNotice}
                </Link>
                <Suggestions />
                <nav>
                    {/*<NavLink 
                        to="/host"
                        className={({ isActive }) => isActive ? "active-nav" : null }
                    >
                        Host
                    </NavLink>*/}
                    {/*<NavLink 
                        to="/about"
                        className={({ isActive }) => isActive ? "active-nav" : null }
                    >
                        About
                    </NavLink>*/}
                    {apiLinks}
                </nav>
            </header>
            <div className="header--dir">
                <Link className="header--dir-link" to="/" >Home</Link>
                {dir}
            </div>
        </div>
    )
}