import React, { useContext } from "react";
import { NavLink } from "react-router-dom";
import Entry from "./Entry";
import { AppState } from "../..";
import maximizeIcon from "../../assets/images/maximize.png";
import minimizeIcon from "../../assets/images/minimize.png";
import TokenText from "../../components/TokenText";
import serverIcon from "../../assets/images/server-icon.png";
import clientIcon from "../../assets/images/client-icon.png";
import FlexPrev from "../../components/FlexPrev";

export default function FuncCatgeory({ name, description, functions, windowWidth, windowHeight, page, link, expLink, section, type, noApi }) {
    const { apiPages, tagCategories, selectedTags, updateTags } = useContext(AppState);
    const screenWidth = window.screen.width
    const [maximized, setMaximized] = React.useState(false)
    const [descMaximized, setDescMaximized] = React.useState(false)
    const categoryClass = maximized ? "func--grid" : "func--flex"
    const maxColumns = 3
    const gridColumns = windowWidth > windowHeight
        ? Math.min((Math.ceil((windowWidth - 400) / (screenWidth / maxColumns))), functions.length) : 1

    const categoryStyle = {
        gridTemplateColumns: "1fr ".repeat(gridColumns)
    }

    functions.sort(function(a, b) {return a.name > b.name})

    const funcPrevs = functions.map(func => (
        <NavLink
            to={`/api/${page}/${func.name}`}
        >
            <FlexPrev>
                {func.tags.includes("Server") && <img className="api--server-icon" src={serverIcon} title="Server function" ></img>}
                {func.tags.includes("Client") && <img className="api--client-icon" src={clientIcon} title="Client function" ></img>}
                {func.name}
            </FlexPrev>
        </NavLink>
    ))
    
    const funcs = functions.map(func => {
        func.noApi = func.noApi || noApi
        return (
            <Entry
                { ...func }
                page={page}
                link={link}
                expLink={expLink}
                section={section}
                type={type}
            />)
    })

    const categoryFlex = (
        <div className="func--flex">
            {funcPrevs}
        </div>
    )

    const descStyle = {
        maxHeight: descMaximized ? "" : "100px"
    }

    const categoryGrid = (
        <div className="func--grid" style={categoryStyle}>
            {funcs}
        </div>
    )

    function toggleMaximized() {
        //console.log(maximized)
        setMaximized(prevState => !prevState)
    }

    function toggleDescMaximized() {
        setDescMaximized(prevState => !prevState)
    }

    const headerElement = (
        <div className="api--category-header">
            <img
                src={maximized ? minimizeIcon : maximizeIcon}
                height="24px"
                align="center middle"
                style={{ marginLeft: "5px", color: "" }}
                alt=""
            />
            <h3
                className="api--category-name func--category-button"
                onClick={() => toggleMaximized()}
            >
                {`${name} `}
            </h3>
            <p>
                {`(${functions.length})`}
            </p>
        </div>)

    const descElement = (
        <p
            className="func--text func--category-description"
            style={descStyle} 
            onClick={() => toggleDescMaximized()}
        >
            {description
                ? <TokenText
                    className="func--text"
                    text={description}
                />
                : ""}
        </p>)

    if (functions && functions.length > 0) {
        return(
            <div className="api--category">
                {headerElement}
                {descElement}
                {categoryFlex}
                {maximized ? categoryGrid : ""}
                <hr />
            </div>
        )
    }

    return false
}