import { useContext } from "react";
import { AppState } from "..";
import { useNavigate } from "react-router-dom";
import { useSignals } from "@preact/signals-react/runtime";

export default function Suggestions() {
    const {
        searchQuery,
        apiPages,
        updateSearch,
        searchFocus,
        apiPage,
        selectedTags,
        updateQuery
    } = useContext(AppState);
    let navigate = useNavigate()
    useSignals();
    const filteredSuggestions = apiPages.value
        .flatMap(page => 
            page.categories.flatMap(category => 
                category?.children?.map(func => ({
                    ...func,
                    page: page.title
                }))
            )
        )
        .sort((a, b) => a.name.localeCompare(b.name))
        .filter(func => 
            func?.name.toLowerCase().includes(searchQuery.value.toLowerCase())
        );
    
    const suggestionsElements = filteredSuggestions.map(func => {
        const page = func.page.toLowerCase()
        return (
            <div
                className="search--suggestion"
                onClick={() => {
                    updateQuery(func.name);
                    apiPage.value = page;
                    selectedTags.value = [];
                    navigate(`/api/${page}`)}}
            >
                <p
                    className="search--suggestion-name">
                        {func.name}
                </p>
                <p
                    className="search--suggestion-page">
                        {page}
                </p>
            </div>
        )
    });

    return (
        <div className="search" >
            <input
                className="search--input"
                type="text"
                onChange={updateSearch}
                onFocus={() => searchFocus.value = true}
                placeholder="Search"
            />
            <div className="search--suggestions" >
                {searchQuery.value === ""
                    ? ""
                    : suggestionsElements}
            </div>
        </div>
    )
}