import {
    createSearchParams,
    generatePath,
    useNavigate,
    useSearchParams
} from 'react-router';
import { AppState } from '..';
import { useContext } from 'react';

export const useMyNavigate = () => {
    const {
        selectedTags,
        searchQuery
    } = useContext(AppState);
    const navigate = useNavigate();
    const useSearch = useSearchParams();
    const searchParams = useSearch[0]
    //console.log(useSearch)
    return (url, params) => {
        const restParams = Object.fromEntries(
            Object.keys(params)
                .filter(x => !x.match(/^\w+$/) || !url.match(new RegExp(`:${x}\\b`)))
                .map(x => [x, params[x]])
        );
        navigate({
            pathname: generatePath(url, params),
            search: createSearchParams(restParams).toString(),
        });
    };
};