import Highlight from "react-highlight";
import { vs2015 as highlightStyle } from 'react-syntax-highlighter/dist/esm/styles/hljs';
import { highlightWords } from "../utils";
import { Link, NavLink } from "react-router-dom";
import externalLinkIcon from "../assets/images/external-link.png"
import { useContext } from "react";
import { AppState } from "..";
import TokenText from "./TokenText";

export function EntryCode({type, code}) {

    if (!code) {
        return  ''
    }

    const element = type === 'function'
        ? <Highlight className="language-lua">
            {code}
        </Highlight>
        : code

    return (
        <div className="func--code">
            {/*example*/}
            {/*<SyntaxHighlighter
                language="lua"
                style={highlightStyle}
                customStyle={{background: "none"}}
                wrapLongLines
            >
                {example}
            </SyntaxHighlighter>*/}
            {element}
        </div>
    )
}

export function EntryHeader({page, experimental, name, status, peer}) {

    const headerText = <NavLink
            to={`/api/${page}/${name}`}
            className="entry--header-link"
        >
            {name}
        </NavLink>
    return (
        <div className="func--header">
            {headerText}
            {experimental && <span className="func--text func--experimental">{`Experimental`}</span>}
            {peer && <span className="func--text entry--peer">{`${peer.toUpperCase()} ONLY`}</span>}
            {status && <span className="func--text func--status">{` (${status})`}</span>}
        </div>
    )
}

export function EntryExample({name = '', type = '', inputs = [], outputs = []}) {
    const decoration = {
        tag: {start: '='},
        function: {start: '(', end: ')', always: true, split: ', '}
    }
    const showStart = inputs.length > 0 || decoration[type]?.always
    const showEnd = outputs.length > 0 || decoration[type]?.always

    const inputExamples = inputs.map((arg, index) => (
        <span key={index} className="func--argument courier">
            {decoration[type]?.split
                && index > 0
                && (
                    <span className="func--text func--func">
                        {decoration[type]?.split ?? ' '}
                    </span>)}
            {arg.optional ? `[${arg.name}]` : arg.name}
        </span>
    ))

    const outputExamples = outputs.map((ret, index) => (
        <span key={index} className="func--return courier">
            {index > 0 && <span className="func--text">, </span>}
            {ret.name}
        </span>
    ))
        
    const exampleOutputs = (outputs.length > 0 
        ? <>{outputExamples}<span className="func--text"> = </span></> 
        : ""
    )
    const exampleInputs = (inputs.length > 0 
        ? <>{inputExamples}</> 
        : ""
    )

    const start = `${name}${showStart ? (decoration[type]?.start ?? '') : ''}`
    const end = showEnd ? (decoration[type]?.end ?? '') : ''

    return (
        <div className="func--example func--func courier">
            {exampleOutputs}
            {start}
            {exampleInputs}
            {end}
        </div>
    )
}

export function EntryDescription({deprecateNotice, text}) {

    return (
        <div className="func--description">
            {deprecateNotice && <p className="red bold">This function will be deprecated in the next update!</p>}
            {text
                ? <TokenText
                    className="func--text"
                    text={text}
                />
                : ""}
        </div>
    )
}

export function EntryTags({name, tags, experimental, link, expLink, section, noApi}) {
    const { apiPages, tagCategories, selectedTags, updateTags, tdPatch } = useContext(AppState);

    tags?.sort()
    
    const tagElements = tags?.map((tag, index) => {
        const selected = selectedTags.value.includes(tag)
        return (
            <span
                key={index}
                className={`func--prev ${selected ? "red" : ""}`}
                onClick={() => updateTags(tag)}
            >
                {tag}
            </span>
        )
    })

    return (
        <div className="func--flex func--tags">
            {tagElements}

            {!noApi
                ? <span className={`func--prev`}>
                    <Link
                        to={`${experimental ? expLink : link}${name}`} 
                        target="_blank" 
                        rel="noopener noreferrer" 
                        className="api-link"
                    >
                        {experimental ? "Experimental API" : `${section} API`}
                        <img
                            src={externalLinkIcon}
                            height="10px"
                            align="center middle"
                            style={{ marginLeft: "5px", color: "" }}
                            alt=""
                        />
                    </Link>
                </span>
                : ""}
        </div>
    )
}

export function EntryTable({table}) {

    if (!table) {
        return ''
    }

    const tableHeaders = <thead>
        <tr>
            {table[0]?.headers.map(header => {
                return (
                    <th key={header} >
                        {header}
                    </th>
                )
            })}
        </tr>
    </thead>
    const tableData = <tbody>
        {table[0]?.data.map(data => {
            const content = data.map(content => {
                return (
                    <td key={content} >
                        {content}
                    </td>
                )
            })

            return (
                <tr key={data[0]}>
                    {content}
                </tr>
            )
        })}
    </tbody>

    return (
        <div className="func--table">
            <table className="func--text">
                {tableHeaders}
                {tableData}
            </table> 
        </div>
    )
}

export function EntryExchanges({type = 'tag', inputs = [], outputs = [], isPage = false}) {
    const showOutputs = type !== null && type !== 'tag'
    const argRetStyle = 
        type === 'tag'
        ? `"arguments arguments arguments arguments"`
        : ((inputs.length > 0 || outputs.length > 0) && (inputs.length > 1 && outputs.length > 1) && !isPage)
            ? `"returns returns arguments arguments"`
            : `"arguments arguments arguments arguments"
                "returns returns returns returns"`

    // if neither is above 0 or both are above 1
    
    const funcStyle = {
        gridTemplateAreas: `
            ${argRetStyle}
        `
    }
    
    const inputsList = inputs.map((arg, index) => (
        <p key={index} className="func--argument courier">
            {arg.name}
            <span className="func--text" style={{ marginLeft: "5px"}} >
                (<span className="courier">
                    {arg.type}
                </span>
                {arg.optional &&  ", optional"}
                ) - {arg.description}
            </span>
        </p>
    ))

    const outputsList = showOutputs
        ? outputs.map((ret, index) => (
            <p key={index} className="func--return courier">
                {ret.name}
                <span className="func--text" style={{ marginLeft: "5px"}} >
                    (<span className="courier">
                        {ret.type}
                    </span>) - {ret.description}</span>
            </p>
        ))
        : ''

    const inputsElement = (
        <div className="func--arguments">
            <p className="func--text">Arguments</p>
            {
                inputs[0]
                    ? <>{inputsList}</>
                    : <p className="func--argument">none</p>
            }
        </div>)

    const outputsElement = showOutputs
        ? (
        <div className="func--returns">
            <p className="func--text">Return values</p>
            {
                outputs[0]
                    ? <>{outputsList}</>
                    : <p className="func--return">none</p>
            }
        </div>)
        : ''

    return (
        <div className="entry--exchanges" style={funcStyle}>
            {inputsElement}

            {outputsElement}
        </div>
    )
}