import React, { useContext } from "react";
import {
    Link,
    NavLink,
    navigate,
    useNavigate
} from "react-router-dom";
import externalLinkIcon from "../../assets/images/external-link.png";
import backIcon from "../../assets/images/back-icon.png";
import { AppState } from "../..";
import Highlight from "react-highlight";
import {
    EntryHeader,
    EntryExample,
    EntryExchanges,
    EntryDescription,
    EntryTable,
    EntryCode,
    EntryTags
} from "../../components/EntryComponents"

export default function EntryPage({ tags, name, description, inputs, outputs, code, deprecateNotice, status, example, table, noApi, isPopup, patch, page, link, expLink, section, type, original }) {
    const { apiPages, tagCategories, selectedTags, updateTags, tdPatch } = useContext(AppState);
    patch = patch || original
    let navigate = useNavigate()
    const hasPatch = patch !== null
    const experimental = hasPatch && patch > tdPatch
    const peers = ['Server', 'Client'].filter(v => tags.includes(v))
    const peer = peers.length === 1 && peers[0]

    const backElement = <div
            className="func--back"
            onMouseUp={()=>{navigate(`/api/${page}`)}}
            onTouchEnd={()=>{navigate(`/api/${page}`)}}
        >
            <img
                className="func--back-image"
                src={backIcon}
                alt="Back"
            />
        </div>

    const headerElement = (
        <EntryHeader
            page={page}
            experimental={experimental}
            name={name}
            status={status}
            peer={peer}
        />)
        
    const exampleElement = (
        <EntryExample
            name={name}
            type={type}
            inputs={inputs}
            outputs={outputs}
        />)
        
    const exchangesElement = (
        <EntryExchanges
            type={type}
            inputs={inputs}
            outputs={outputs}
            isPage={true}
        />)

    const descriptionElement = (
        <EntryDescription
            deprecateNotice={deprecateNotice}
            text={description}
        />)
        
    const tableElement = (
        <EntryTable
            table={table}
        />)
            
    const codeElement = (
        <EntryCode
            type={type}
            code={example}
        />)
        
    const tagElement = (
        <EntryTags
            name={name}
            tags={tags}
            experimental={experimental}
            link={link}
            expLink={expLink}
            section={section}
            noApi={noApi}
        />)

    return (
        <div className="func--page" >
            {backElement}
            <div className="func--page-content" >
                <div style={{ padding: "5px" }} >

                    {descriptionElement}

                    {tableElement}
                </div>
                <div className="entry--page-side" >
                    {headerElement}
                
                    {exampleElement}

                    {exchangesElement}
                    
                    {tagElement}
                </div>
            </div>
            {codeElement}
        </div>
    )
}