import React, {
        useState,
        useEffect,
        //createContext,
        useContext
    } from "react"
import {
    checker,
    executeOnField,
    sanitizeString
} from "../utils"
import {
    useLocation,
    //useOutletContext,
    //useParams,
    //useNavigate
} from "react-router"
import { useSignals } from "@preact/signals-react/runtime"

import FuncCategory from "./Api/EntryCategory"
import Entry from "./Api/Entry"
import EntryPage from "./Api/EntryPage"

import { AppState } from "../index"
import { useMyNavigate } from "../components/MyNavigate"
import ApiRegistry from "./Api/ApiRegistry"
import FlexPrev from "../components/FlexPrev"
import serverIcon from "../assets/images/server-icon.png";
import clientIcon from "../assets/images/client-icon.png";

export default function Documentation() {
    const [windowWidth, setWindowWidth] = useState(window.innerWidth)
    const [windowHeight, setWindowHeight] = useState(window.innerHeight)
    const [tagsFieldWidth, setTagsFieldWidth] = useState(window.innerWidth)

    const {
        apiPages,
        tagTypes,
        selectedTags,
        updateTags,
        searchQuery,
        //updateSearch,
        tdPatch,
        //apiPage
    } = useContext(AppState);
    let navigate = useMyNavigate()//useNavigate()
    useSignals();

    const hash = useLocation()
    //const params = useParams()
    const pathname = hash.pathname.split("/")
    const requestedPage = sanitizeString(pathname[2] || "")
    const requestedFunction = sanitizeString(pathname[3] || "")
    const pages = apiPages.value.map(page => {
        const title = page.title
        return title.toLowerCase()
    })
    const isPage = pages.includes(requestedPage)
    const page = apiPages.value.find( page => {
        const title = page.title
        return title.toLowerCase() === (isPage
            ? requestedPage
            : "script"
        )
    })
    //const selectingTags = selectedTags.length > 0
    const pageNoApi = page.noApi
    const pageType = page.type || 'none'
    const categories = page.categories
    //const tagCategories = []
    let requestedFunctionObj = {}
    let tags = []
    let tagCounts = []
    let paramFunctionExists = false

    if (!isPage) {
        navigate('/api/:section', { section: 'script' })
    }

    //console.log(hash)

    const noMatches = 
        <h1 
            className="white"
            style={{display: "flex", flexDirection: "column", alignItems: "center", textAlign: "center", gap: "10px" }}
        >
            No matches for 
            {
                searchQuery.value !== "" 
                    ? ` "${searchQuery.value}"`
                    : ""
            }
            {
                searchQuery.value !== "" && selectedTags.value.length > 0 
                    ? " with"
                    : ""
            }
            {
                selectedTags.value.length > 0
                    ? " selected tags"
                    : ""
            }
            {
                selectedTags.value.length > 0
                    ? <div style={{ display: "flex", justifyContent: "center", flexDirection: "row", gap: "5px", flexWrap: "wrap" }} >
                        {selectedTags.value.map(tag => {
                        return <div className="api--tag" style={{ height: "fit-content", maxWidth: "fit-content" }} >
                            {tag}
                        </div>
                        })}
                    </div>
                    : ""
            }
        </h1>

    const categoryElements = categories.map((category) => {
        let { id, name, description, children } = category
        if (!paramFunctionExists) {
            paramFunctionExists = children?.some(func => {
                return func.name?.toLowerCase() === requestedFunction.toLowerCase()
            })
        }

        if (requestedFunction !== "") {
            const filteredFunctions = children?.filter(func => {
                return func.name?.toLowerCase() === requestedFunction.toLowerCase()
            })
    
            requestedFunctionObj = filteredFunctions.length > 0
                ? filteredFunctions[0]
                : requestedFunctionObj
        }

        if (selectedTags.value.length > 0 || searchQuery.value !== "") {
            children = children?.filter(func => {
                let matchesSearch = searchQuery.value !== ""
                    ? func.name?.toLowerCase().includes(searchQuery.value.toLowerCase())
                    : true

                const matchesTags = selectedTags.value.length > 0
                    ? checker(func.tags, selectedTags.value)
                    : true
                    
                if (searchQuery.value !== "" && !matchesSearch) {
                    matchesSearch = executeOnField(func?.children, 'name', (name) => name.toLowerCase().includes(searchQuery.value.toLowerCase()), true);
                }

                return matchesSearch && matchesTags
            });
        }

        // if (selectedTags.value.length > 0 || searchQuery.value !== "") {
        //     children = children?.filter(child => {
        //         let matchesSearch = searchQuery.value !== ""
        //             ? child.name?.toLowerCase().includes(searchQuery.value.toLowerCase())
        //             : false

        //         let matchesTags = child.tags?.length > 0
        //             ? checker(child.tags, selectedTags.value)
        //             : false
                    
        //         if (searchQuery.value !== "" && !matchesSearch) {
        //             matchesSearch = executeOnField(child?.children, 'name', (name) => name.toLowerCase().includes(searchQuery.value.toLowerCase()), true);
        //         }
        
        //         // if (func.tags?.length > 0 && !matchesSearch && !matchesTags) {
        //         //     matchesTags = executeOnField(func?.children, 'tags', (tags) => checker(tags, selectedTags.value), true);
        //         // }

        //         return matchesSearch || matchesTags
        //     });
        // }

        // gathering tags
        children?.map(func => {
            const funcTags = func.tags
            func.patch > tdPatch && !funcTags.includes("Experimental") && funcTags.push("Experimental")
            tags = tags.concat(funcTags).filter((value, index, self) => {
                return value !== undefined ? self.indexOf(value) === index : ""
            })

            return ""
        })

        // gathering tag counts for each tag
        children?.map(func => {
            (func.tags?.length > 0 && (selectedTags.value.length === 0 || selectedTags.value.every(value => func.tags?.includes(value)))) && func.tags?.map(tag => {
                tagCounts[tag] = (tagCounts[tag] || 0) + 1

                return ""
            })

            return ""
        })

        if (children?.length > 0) {
            return (
                pageType === 'registry'
                ? <ApiRegistry
                    {...category}
                    children={children}
                    searchQuery={searchQuery}
                    selectedTags={selectedTags}
                />
                : <FuncCategory
                    key={id}
                    name={name}
                    description={description}
                    functions={children}
                    updateTags={updateTags}
                    windowWidth={windowWidth}
                    windowHeight={windowHeight}
                    page={requestedPage}
                    link={page.link}
                    expLink={page.expLink}
                    section={page.title}
                    type={page.type}
                    noApi={pageNoApi}
                />
            )
        }

        return false

    }).filter(element => element !== false)

    /*console.log(requestedFunction + " " + paramFunctionExists)*/

    tags.sort()
    tagTypes.value.sort((a, b) => a.name > b.name)

    let funcPage = ""

    if (paramFunctionExists) {
        const functionObj = categories
            .map(category => category.children)
            .flat()
            .find(func => func.name?.toLowerCase() === requestedFunction.toLowerCase());

        //console.log(functionObj)

        if (requestedFunction !== functionObj?.name) {
            navigate(`/api/${requestedPage}/${functionObj.name}`)
        }

        functionObj.noApi = functionObj.noApi || pageNoApi
        //console.log(pageNoApi)

        funcPage = (
            windowWidth > windowHeight
            ? <EntryPage
                { ...functionObj }
                isPopup={true}
                page={requestedPage}
                link={page.link}
                expLink={page.expLink}
                section={page.title}
                type={pageType}
            />
            : <Entry
                { ...functionObj }
                isPopup={true}
                page={requestedPage}
                link={page.link}
                expLink={page.expLink}
                section={page.title}
                type={pageType}
             />
        )
    } else if (searchQuery.value !== requestedFunction) {
        searchQuery.value = searchQuery.value !== ""
            ? sanitizeString(searchQuery.value)
            : requestedFunction
    }

    /*const tagElements = tags.map(tag => {
        const index = selectedTags.value.indexOf(tag)
        const selected = index > -1
        const tagCount = tagCounts[tag]
        const matches = tagCount > 0
        const styled = { color: `${matches ? "limegreen" : "red"}` }
        return (
            tagCount > 0
            ? <span
                className={`func--prev`}
                onClick={() => updateTags(tag)}
            >
                <span className={`${selected ? "red" : ""}`} >{tag}</span>
                <span className="tag--count" >{tagCount || 0}</span>
            </span>
            : ""
        )
    })*/

    let rows
    let tagCount = 1
    const tagsStyle = {
        height: "0px"
    }

    {
        const tagHeight = 25
        const tagWidth = 150
        const items = tags.length + tagTypes.value.length
        const maxWidth = tagsFieldWidth
        const tagsPerRow = Math.ceil(maxWidth / tagWidth)
        rows = Math.ceil(items / tagsPerRow)
        const height = (rows - 1) * (tagHeight + 5) - 5
        //const width = Math.min(tags.length * 150, maxWidth) - 150

        tagsStyle.height = `${height + 50}px`
    }

    const tagTypeElements = tagTypes.value.map(type => {
        const sortedTags = [...type.tags].sort();
        const elements = sortedTags
            .filter(tag => tags.includes(tag))
            .map(tag => {
                const selected = selectedTags.value.includes(tag)
                const tagCount = tagCounts[tag]

                return (
                    <div
                        onClick={() => updateTags(tag)}
                    >
                        <FlexPrev>
                            {tag === "Server" && <img className="api--server-icon" src={serverIcon} title="Server function" ></img>}
                            {tag === "Client" && <img className="api--client-icon" src={clientIcon} title="Client function" ></img>}
                            <span className={`${selected ? "red" : ""}`} >{tag}</span>
                            <span className="api--tag-count" >{tagCount || 0}</span>
                        </FlexPrev>
                    </div>
                )
            });
        let bottom
        if (elements.length > 0) {
            bottom = tagCount % rows === 0 && rows > 2
            //console.log(bottom, type.name, tagCount, rows, tagCount / rows)
            tagCount = tagCount + elements.length + 1
        }

        if (bottom) {
            tagCount++
        }
        return (
            elements.length > 0 ? (
                <>
                    {bottom
                        ? <div className="memes" style={{width: '', height: '25px'}}></div>
                        : ''}
                    <h3 className="api--tag-header white">{type.name}</h3>
                    {elements}
                </>
            ) : ''
        )
    })

    const miscTagElements = tags
        .filter(tag => !tagTypes.value.some(type => type.tags.includes(tag)))
        .map(tag => {
            const tagsIndex = selectedTags.value.indexOf(tag)
            const selected = tagsIndex > -1
            const tagCount = tagCounts[tag]

            return (
                <div
                    className="api--tag"
                    onClick={() => {
                        console.log("hey")
                        updateTags(tag)
                    }}
                >
                    <span className={`${selected ? "red" : ""}`} >{tag}</span>
                    <span className="api--tag-count" >{tagCount || 0}</span>
                </div>
            )
        })

    const miscTagHeader = miscTagElements.length > 0
        ? <h3 className="api--tag-header white">
            Misc
        </h3>
        : ""

        
    //console.log(tagCount % rows == 0 && rows > 2, 'Misc', tagCount, rows, tagCount / rows)
    const tagElement = <div
            className="api--tags"
            id="tag-field"
            style={tagsStyle}
        >
            {tagTypeElements}
            {(tagCount % rows === 0 && rows > 2)
                ? <div className="memes" style={{width: '', height: '25px'}}></div>
                : ''}
            {miscTagHeader}
            {miscTagElements}
        </div>

    const apiPageElement = (
        <div 
            className="func--background" 
            style={paramFunctionExists ? { overflow: "hidden", position: "fixed" } : {}}
        >
            {/*<h3 style={{color: "white", padding: "none", margin: "none"}}>Tag filtering:</h3>
            <div className="func--flex func--tags">
                {filterElements}
            </div>*/}
            {tagElement}
            <div>
                {categoryElements.length > 0
                    ? categoryElements
                    : noMatches}
            </div>
        </div>
    )

    useEffect(() => {
        const handleResize = () => {
            const tagsField = document.getElementById('tag-field');

            setWindowWidth(window.innerWidth);
            setWindowHeight(window.innerHeight);

            if (tagsField) {
                setTagsFieldWidth(tagsField.offsetWidth);
            }

            //console.log(tagsFieldWidth);
        };

        handleResize();
    
        window.addEventListener('resize', handleResize);

        return () => {
            window.removeEventListener('resize', handleResize);
        };
    }, []);

    return (
        <div className="api" >
            {paramFunctionExists
                ? funcPage
                : apiPageElement
            }
        </div>
    )
}